// ============================================================
// 命定之诗 · 地图覆盖脚本 v0.100
// 生成时间: 2026-11-06-01-43-12
// 标记数  : 169
// 坐标处理: 原样输出
//
// 会覆盖: 名称 / 分组 / 图标 / 颜色 / 坐标 / 描述 / 图片链接
// 会删除: 这份数据里没有的标记
// 运行完请刷新页面（F5）
// ============================================================
(() => {
  const SHOW = (t) => {
    try { console.log(t); } catch (e) { void e; }
    try {
      if (typeof toastr !== "undefined") {
        toastr.info(String(t).replace(/\n/g, "<br>"), "地图覆盖", {
          timeOut: 0, extendedTimeOut: 0, closeButton: true,
          tapToDismiss: false, progressBar: false, positionClass: "toast-top-center"
        });
      }
    } catch (e) { void e; }
    try { alert(t); } catch (e) { void e; }
    return t;
  };

  // 旧名 → 现名：只在按现名找不到标记时才回退使用
  // v0.100 移除 "翼民圣国": "梵尼亚" —— 梵尼亚是独立地点，
  //   该别名会让两条记录抢同一个标记，产出重复 id，导致其中一个标记不显示。
  // 新增 "圣都梵尼亚": "梵尼亚" —— 官方名 → 本数据名，反向迁移时沿用原标记 id。
  const ALIAS = {
    "圣都梵尼亚": "梵尼亚",
    "精灵王庭": "卢森提亚王庭",
    "永寂雷林": "永寂密林",
    "冬帷林海": "冬帷林盘",
    "月隐谷原": "月隐盆地"
  };
  const OLD_OF = {};
  Object.keys(ALIAS).forEach(k => { const v = ALIAS[k]; (OLD_OF[v] = OLD_OF[v] || []).push(k); });

  // [名称, 分组, 图标, 颜色, nx, ny, 描述, 图片链接]
  const DATA = [
    ["阿勒穆特","小型城邦","fa-solid fa-city","#ffd43b",0.491284,0.793112,"刺客们虽没有祖国，却拥有一座名为阿勒穆特的首都。这座隐匿于鹰之山脉深谷中的“影子之城”，被外界忌惮为萨赫拉联邦真正的幕后主宰。在那死寂的街道上，你永远听不到孩童的嬉笑，唯有磨利刀刃的寒音在回荡。这里运作着世界上最冷酷的交易：你在别处掉落的一枚钱币，或许就是在此地签下的一份死亡契约；而传说中那位教团宗师，更能从世间任何一片阴影中现身索命，宛如沙漠中最无形亦最致命的流风，无处不在，又无迹可寻。",["https://wsrv.nl/?url=files.catbox.moe/gibint.png","https://wsrv.nl/?url=files.catbox.moe/o21a3i.png","https://wsrv.nl/?url=files.catbox.moe/1aq2uk.png"]],
    ["阿兹哈尔","巨型城邦","fa-solid fa-city","#ffd43b",0.527073,0.714937,"若想见证凡人最极致的荣耀与疯狂，你必须造访阿兹哈尔——这颗沙漠中最璀璨的明珠，一座完全由黄金与享乐堆砌而成的娱乐之都。在城中央那座宏伟的“烈日大角斗场”，英雄与巨兽的死斗从未停歇，震彻云霄的欢呼声足以传出数里之远。在这里，鲜血被视为最好的美酒，吟游诗人用诗歌换取黄金，角斗士则用敌人的热血为自己加冕；正如当地人所信奉的那样，在这片狂热的土地上，唯有胜利者与享乐者值得被铭记。",["https://wsrv.nl/?url=files.catbox.moe/zr8xrc.png","https://wsrv.nl/?url=files.catbox.moe/fj8vvi.png","https://wsrv.nl/?url=files.catbox.moe/mzqu4i.png"]],
    ["艾尔文海姆","大型城市/世界树之城","fa-solid fa-location-dot","#63e6be",0.235936,0.771038,"那里的居民从不说自己住在城里，只说住在世界树的影子里。远望的人看不见街道，只看见一株巨树。入夜后，叶脉泛起银光，居民称作树辉之夜。艾尔文海姆不是一座城，而是一首始终没有离开摇篮的谣曲",[]],
    ["艾琉德雷姆·尼尔","泣空遗迹/冒险区域","fa-solid fa-location-dot","#78c6ff",0.38817,0.586114,"在距地三万米的极高空，“天穹涡流”的永续风暴托举着这座游荡的巨型空岛——它是昔日精灵与翼民联手铸就的战略奇观“圣律天穹”，也是第二次位面入侵末期自毁升空、将主位面通道与异界神明死死钉在苍穹之上的巨大棺椁。\n\n遗迹外围的泣歌云海美得恍若幻梦，空岛云鲸与流光歌隼在富集的魔力霞光中巡游；可一旦穿过风暴、踏上那片融合了精灵雅艺与翼民圣辉的断壁残垣，迎接来客的唯有不散的异界低语与魔力畸变。昔日留守核心的古代翼民守卫早已在污染中异化为怪物，与被封印的异界残留一同游荡在破碎的众神殿堂间。梵尼亚的视线始终紧盯着这片高空禁区，但真正阻绝冒险者与学者的并非圣国的警戒，而是那三万米的绝命天堑，以及封印深处从未平息的异界余悸。",[]],
    ["艾瑟嘉德","巨型城邦","fa-solid fa-city","#000000",0.526638,0.534575,"若你渴望目睹那道横跨天穹的奇迹，就必须前往帝国的首都——“辉光之城”艾瑟嘉德。传说中，初代皇帝曾用一块完整的魔法水晶雕刻出了那座宏伟的“白金拱桥”。这不仅仅是建筑，更是神权的精密仪器：每当黎明破晓，第一缕阳光会穿过剔透的桥拱，精准地照亮皇宫那刺破云霄的尖顶之下的王座，臣民们坚信，那是太阳在向他们的统治者致意。而在盛大的“双狮鹫节”，这种威严将达到顶峰——皇帝陛下会在真正的双头狮鹫伴飞下巡视苍穹，向整座大陆宣告帝国不可侵犯的至高权柄。",["https://wsrv.nl/?url=files.catbox.moe/sk9fom.png","https://wsrv.nl/?url=files.catbox.moe/vz75p4.png","https://wsrv.nl/?url=files.catbox.moe/y93pzm.png","https://wsrv.nl/?url=files.catbox.moe/wclssh.png","https://wsrv.nl/?url=files.catbox.moe/xo7cjh.png","https://wsrv.nl/?url=files.catbox.moe/023yu0.png","https://wsrv.nl/?url=files.catbox.moe/whe9tz.png"]],
    ["艾瑟尼亚省","行省","fa-solid fa-location-dot","#78c6ff",0.526646,0.527202,"首都与礼制核心所在省份",[]],
    ["暗澜群岛","群岛","fa-solid fa-location-dot","#63e6be",0.24054,0.940157,"大陆西南精灵国度附近的岛屿群",[]],
    ["奥古斯提姆帝国","帝国","fa-solid fa-flag","#000000",0.503395,0.558516,"诸界余晖下的永恒霸权:“我们不乞求神明的怜悯，也不依赖自然的馈赠。奥古斯提姆的每一寸疆土，都是用剑刃从世界手中夺来的。在女皇陛下的注视下，软弱是唯一的原罪，而征服是最高的敬意。”\n\n在大陆东部的广袤平原上，奥古斯提姆帝国的双头狮鹫旗帜是唯一被允许飘扬的色彩——金色象征着金谷城无尽的麦浪与财富，深红色则象征着铁炉堡为了捍卫秩序所流淌的铁血。作为当前人类文明中军事实力最强的霸主，帝国本身就是一座森严的壁垒。在其首都“辉光之城”艾瑟嘉德，第六层级的至高统治者维奥莱塔·马克西姆·奥古斯塔女皇，以她不容置疑的权威掌控着波流斯、霍亨伯格等六大古老家族的命运。在这里，法律允许你向任何神明祈祷，但你的剑与忠诚必须属于帝国。面对西境卡拉什利亚斯兽族联盟的咆哮，以及位面入侵留下的阴影，奥古斯提姆展现出了令人战栗的务实与强势——它不寻求被爱戴，只要求被服从。",["https://wsrv.nl/?url=files.catbox.moe/xvfs6x.png"]],
    ["巴哈尔港","","fa-solid fa-location-dot","#ffd43b",0.579781,0.772648,"",[]],
    ["白港","港口","fa-solid fa-city","#ffffff",0.683756,0.249795,"若要在北境寻觅财富，你必须前往白港。在那儿，由钢铁与巨兽肋骨铸成的破冰船，船首如獠牙般劈开的不是波浪，而是冰封的海洋。码头上，满载而归的船长们交易着从深渊夺来的海龙皮革与巨乌贼墨囊，空气中永远混杂着咸腥、烈酒与钱币的味道——正如水手所言，冰海的每一次封冻都是为勇敢者准备的盛宴，而那比风雪更苍凉的船歌，便是这盛宴唯一的伴奏。",["https://wsrv.nl/?url=files.catbox.moe/u59p2f.png","https://wsrv.nl/?url=files.catbox.moe/set7mb.png","https://wsrv.nl/?url=files.catbox.moe/mvc4yu.png"]],
    ["白色据点","营地","fa-solid fa-campground","#845ef7",0.404393,0.809083,"与黑色据点遥遥相对的，是那片仿佛童话般散发着柔光的“白色据点”。传说曾有圣者在此陨落，其残存的力量净化了土地，让发光的苔藓为你指路，让林间清泉治愈你的重伤。然而，千万别被这圣洁的表象迷惑——据点内的炼金术士会冷笑着告诉你，这片长满发光蘑菇与歌唱花朵的林地，实则是最致命的捕食场：这里极致的美丽与神迹，不过是为了吸引猎物深入的诱饵，就像他们手中高价出售的解毒剂一样，虽绚烂昂贵，却也是你在这致命童话中活下去的唯一必需品。",["https://wsrv.nl/?url=files.catbox.moe/1bsf0y.png","https://wsrv.nl/?url=files.catbox.moe/nbwvyg.png"]],
    ["白石修道院","大型村庄","fa-solid fa-location-dot","#000000",0.530684,0.494224,"在艾瑟嘉德以北，当首都辉煌的金顶逐渐在视野中隐去，你会来到一个名为“白石”的静谧村庄。这里没有狮鹫的嘶鸣，只有一座朴素的修道院伫立在平缓的山坡之上，俯瞰着尘世。不同于皇宫的精雕细琢，白石修道院由粗糙的灰白色岩石堆砌而成，墙缝里长满了倔强的青苔。这里是帝国退役老兵和苦行僧的归宿，他们常会对过往的旅人讲述那个关于修道院基石的古老寓言——以此告诫世人，在艾瑟嘉德的万丈光芒之外，还有另一种活着的方式。",["https://wsrv.nl/?url=files.catbox.moe/hicdto.png"]],
    ["白石镇","城镇","fa-solid fa-location-dot","#78c6ff",0.524052,0.499985,"位于首都圈北侧的人类城镇节点",[]],
    ["白焰港","港口城市","fa-solid fa-location-dot","#63e6be",0.179694,0.908643,"绕过狭窄的黑石岬角只需两刻钟，但吃水深度会骤降三浔。左舷是静默如林的炮甲板与肃杀的军令号角，右舷已飘来香料、烂橘子和八国粗话的喧嚣。没有引航员敢在转弯时走神，两股洋流在这里绞成了死结。",[]],
    ["白曜城","巨型城邦","fa-solid fa-city","#ffffff",0.568216,0.404005,"在北境，人们说白曜城并非仅仅建在山腹之中，它本身就是山的心脏——城墙是山脉的肋骨，而昼夜不息的巨大熔炉则是它跳动的脉搏。你必须先忍受山峦表面的刺骨严寒，才能深入那被烘烤得温暖如春的地下腹地；在那烈火与轰鸣中，铁匠们的每一次锤击不仅是在锻造对抗黑暗的钢铁与勇气，更构成了整个北境最不屈的心跳。",["https://wsrv.nl/?url=files.catbox.moe/q5ac6o.png","https://wsrv.nl/?url=files.catbox.moe/q762j8.png","https://wsrv.nl/?url=files.catbox.moe/zj646d.png","https://wsrv.nl/?url=files.catbox.moe/q6zyey.png"]],
    ["拜特·纳尔","大型城邦","fa-solid fa-city","#ffd43b",0.515668,0.669382,"你相信不用魔法也能让钢铁歌唱吗？去拜特·纳尔看看吧。作为萨赫拉联邦的学术圣地，这里的学者地位堪比国王，工匠们不仰望神明，只信奉齿轮的精密咬合与炼金公式的绝对真理。他们用发条造出比飞龙更精巧的造物——无论是会思考的机械鸟，还是能射穿龙鳞的火枪。学者们自豪地宣称，这座“技术之城”的心脏绝非魔力水晶，而是那一座巨大的金色穹顶，因为里面贮藏的浩瀚知识，才是驱动整个联邦生生不息的真正动力。",["https://wsrv.nl/?url=files.catbox.moe/ajx004.png","https://wsrv.nl/?url=files.catbox.moe/vt8k8x.png","https://wsrv.nl/?url=files.catbox.moe/xsdkxv.png","https://wsrv.nl/?url=files.catbox.moe/otps33.png"]],
    ["暴风沙漠","沙漠","fa-solid fa-location-dot","#78c6ff",0.23908,0.543322,"巡天王庭所在区域，富含魔矿和魔晶",[]],
    ["悲鸣沼泽","沼泽/高危区域（☆☆☆☆）","fa-solid fa-water","#845ef7",0.45631,0.819312,"千万别踏入大陆最南端的悲鸣沼泽，那是一片连最大胆的猛士都会避之不及的死亡禁地。传说这里曾是丰饶的泽国，只因千年前绝望的古国开启了禁忌之门，才让曾经的繁华沦为今日的梦魇：泥沼中翻腾的每一个气泡，都是战死士兵最后的叹息；在这里，活人的呼吸被视为一种罪过，而夜幕下亮起的幽幽鬼火，只会为迷路者指引一条通往永眠的不归路。",["https://wsrv.nl/?url=files.catbox.moe/8d77ei.png","https://wsrv.nl/?url=files.catbox.moe/xl1vmd.png","https://wsrv.nl/?url=files.catbox.moe/rd0xk3.png","https://wsrv.nl/?url=files.catbox.moe/lgc19g.png","https://wsrv.nl/?url=files.catbox.moe/68wa51.png"]],
    ["北部边境带","地区","fa-solid fa-location-dot","#63e6be",0.197603,0.752886,"以疏林、湿润草地和零散丘陵为主，是天镜湖湿地向内陆环境过渡的缓冲区",[]],
    ["北部冻海","海洋/高危","fa-solid fa-location-dot","#78c6ff",0.435325,0.237758,"常年低温、冰况恶劣，是旋涡、破冰航线与高危海况的集中地",[]],
    ["北境内海船","载具","fa-solid fa-campground","#ffffff",0.63727,0.296286,"正在夜间行驶的魔导船...",["https://wsrv.nl/?url=files.catbox.moe/zwetuh.png","https://wsrv.nl/?url=files.catbox.moe/ng6kaz.png","https://wsrv.nl/?url=files.catbox.moe/hmgwnz.png","https://wsrv.nl/?url=files.catbox.moe/0sveiy.png"]],
    ["比比喇泊","封闭的文明/低危区域（☆）","fa-solid fa-location-dot","#ffcc66",0.304134,0.434502,"该区域目前世界书未描述，如想游玩此区域。\n参考提示词如下: 这是一个北面有大裂谷东西两侧各被大山和大湖包围的类似于世外桃源的地方。当地呈现自给自足的状态。\n该地区由于地区封闭可能产生一些特殊习俗或特殊文化，游玩时user口胡即可",[]],
    ["碧霜省","行省/山地","fa-solid fa-location-dot","#78c6ff",0.489028,0.447336,"矿产资源丰富，气候干冷",[]],
    ["边陲之国","DLC内容/巨型城邦/遗迹/中危区域（☆☆☆）","fa-solid fa-city","#845ef7",0.342075,0.902756,"若你的理智能侥幸穿过雷林的轰鸣与迷雾低语，便会抵达南方那片被永恒阴霾笼罩的死寂之地——“边陲之国”。这是一座占地五十万平方公里的宏大废墟，一场永不停歇的“污秽之雨”彻底扭曲了这里的时空与法则。在这里，雨水不再是生命的恩赐，而是记忆的毒药：它能侵蚀物质、固化痛苦，将生者转化为丧失理智的活尸，让亡者化作充满怨念的怪物。从外围悬崖村那相对“安宁”的疯癫，到中层魔女森林中魔法与自然交织的畸变，再到内层王城那深不见底的黑暗，每一步深入都是对认知的凌迟。而在那一切腐化的尽头，污秽之王正端坐在现实的最深处，与白巫女的悲剧命运纠缠共生，等待着有人能终结这场漫长的、关于毁灭的梦魇。",["https://wsrv.nl/?url=files.catbox.moe/21hceo.png","https://wsrv.nl/?url=files.catbox.moe/mbi8io.jpg","https://wsrv.nl/?url=files.catbox.moe/2dodfn.jpg","https://wsrv.nl/?url=files.catbox.moe/hziiyk.jpg","https://wsrv.nl/?url=files.catbox.moe/8py4oy.png","https://wsrv.nl/?url=files.catbox.moe/ze5r5l.jpg"]],
    ["冰峨镇","小型城镇","fa-solid fa-location-dot","#000000",0.518505,0.385801,"",[]],
    ["伯恩·瑞瑟喃斯（骸响之都）","骸响之都/巨型遗迹/极危区域（☆☆☆☆☆）","fa-solid fa-city","#845ef7",0.474099,0.911295,"切勿怀着好奇心去探寻悲鸣沼泽最深处的骸响之都，那绝非冒险，而是赤裸裸的亵渎。这座由森森白骨堆砌而成的城市依旧矗立在死亡气息的封印之中，它既是一个古老王国惨遭背叛的耻辱印记，也是如今亡灵帝国的荣耀前哨。当年撕开位面的法师们至今仍在那里低声吟唱，咒语令“亡者之门”在城中随机开启，让你误以为能窥见故人归来的幻影——但请时刻警惕，这只是猎捕的诱饵，那些法师正饥渴地等待着下一个闯入者，将其炼化为这永恒国度的新国民。",["https://wsrv.nl/?url=files.catbox.moe/qpmzz6.png","https://wsrv.nl/?url=files.catbox.moe/0sdkzj.png","https://wsrv.nl/?url=files.catbox.moe/74lt6y.png","https://wsrv.nl/?url=files.catbox.moe/cnabpi.png","https://wsrv.nl/?url=files.catbox.moe/26z79x.png","https://wsrv.nl/?url=files.catbox.moe/agmlv8.png","https://wsrv.nl/?url=files.catbox.moe/o8kmjj.png"]],
    ["伯伦斯法环","超巨型城邦/魔法学院","fa-solid fa-flag","#000000",0.68757,0.581986,"星轨下的守望者：“我们并非为了避世而登高，亦非为了权柄而集结。当位面交汇的裂痕初次在大地蔓延时，吾辈便立下誓约：此世不应在无知中倾覆。伯伦斯法环伫立于云端，以凡人之躯，为万物测绘那不可见的法则边界。在这里，真理即是责任，观测即是守护。”位于大陆东北沿海六千米高空的伯伦斯法环，是第一次位面战争余晖中建立的法师圣所。它是一座精密运转的观测枢纽，核心“公理圣球”正如一颗永不闭合的眼瞳，时刻校准着阿斯塔利亚位面与虚海间的维度偏差。日冕、月帷、衔尾蛇三院的法师们在此摒弃了凡俗的纷争，他们审视星辰的轨迹，探求着那把足以抵御下一次灾难的真理之钥。法理的余晖从高天垂落，化作了凡世生存的脉动。雾晶港以务实且充满生命力的姿态，成为了连接法环与凡世的门户。这座终年被雨雪与符文微光笼罩的都市，是技术与野心的交汇之地。实验沉降的“三色海雾”在此被捕雾者从波涛中悉数采撷，经由炼金术士之手，将不稳定的灵光凝结为支撑城市运转的晶簇。座落于此的雾晶学院以“心智驾驭奥秘”为训，如同一座熔炉源源不断地吸纳着世界各地的天才，磨砺着那些有望穿过云层、进入法环殿堂的灵魂。每逢十二月，当法环切断一切对外联系，进入封闭观测期时，公理圣球激发的极光将如垂帘般覆盖整个天际。下方的雾晶港亦会随之迎来盛大的“星轨祭”——在祭典最后一天的烟火大会中，璀璨的花火将跃入冬夜，与高天的极光交织共鸣。那一刻，凡世的喧嚣与高天的真理彼此致意，以此慰藉那些在迷雾中为世界守望了整年的灵魂。",["https://wsrv.nl/?url=files.catbox.moe/3x1ifs.png","https://wsrv.nl/?url=files.catbox.moe/di0b4b.png","https://wsrv.nl/?url=files.catbox.moe/d8teyc.png","https://wsrv.nl/?url=files.catbox.moe/89evc3.png","https://wsrv.nl/?url=files.catbox.moe/uc5912.png","https://wsrv.nl/?url=files.catbox.moe/b4tjot.png","https://wsrv.nl/?url=files.catbox.moe/d8cv0k.png","https://wsrv.nl/?url=files.catbox.moe/n184aa.png","https://wsrv.nl/?url=files.catbox.moe/0jb1u0.png"]],
